        container.innerHTML = `<div class="col-span-full text-center py-20 flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border-2 border-dashed border-gray-200"><i class="fas fa-search text-6xl mb-4 opacity-20"></i><p class="font-bold text-lg">لا توجد نتائج مطابقة للبحث</p></div>`;
