function setupCustomDropdowns() {
    // 1. معالجة زر الفتح والإغلاق
    document.querySelectorAll('.custom-dropdown-display').forEach(display => {
        // إزالة المستمعين القدامى
        const newDisplay = display.cloneNode(true);
        display.parentNode.replaceChild(newDisplay, display);

        newDisplay.addEventListener('click', (e) => {
            e.stopPropagation();
            const dropdown = newDisplay.closest('.custom-dropdown');
            const options = dropdown.querySelector('.custom-dropdown-options');

            document.querySelectorAll('.custom-dropdown-options').forEach(opt => {
                if(opt !== options) opt.classList.remove('show');
            });

            options.classList.toggle('show');
            
            // تدوير السهم
            const arrow = newDisplay.querySelector('.fa-chevron-down');
            if(arrow) arrow.style.transform = options.classList.contains('show') ? 'rotate(180deg)' : 'rotate(0deg)';
        });
    });

    // 2. معالجة اختيار العناصر باستخدام (Event Delegation) عشان تشتغل مع العناصر الديناميكية
    if (!window.dropdownsDelegated) {
        document.addEventListener('click', function(e) {
            // لو الضغطة كانت على خيار من القائمة
            const option = e.target.closest('.custom-option');
            
            if (option) {
                const dropdown = option.closest('.custom-dropdown');
                if (!dropdown) return;

                const hiddenSelect = dropdown.querySelector('select');
                const displaySpan = dropdown.querySelector('.custom-dropdown-display span');
                
                // تحديث الشكل
                if (displaySpan) displaySpan.textContent = option.textContent.trim();
                
                // تحديث القيمة وتشغيل الفلتر
                if (hiddenSelect) {
                    hiddenSelect.value = option.dataset.value;
                    hiddenSelect.dispatchEvent(new Event('change')); // هيشغل دالة التواريخ فوراً
                }
                
                // إغلاق القائمة
                const optionsContainer = dropdown.querySelector('.custom-dropdown-options');
                if (optionsContainer) optionsContainer.classList.remove('show');
                
                // إرجاع السهم لشكله الطبيعي
                const arrow = dropdown.querySelector('.fa-chevron-down');
                if(arrow) arrow.style.transform = 'rotate(0deg)';
            } else {
                // لو ضغط برة، اقفل كل القوائم
                document.querySelectorAll('.custom-dropdown-options').forEach(opt => {
                    opt.classList.remove('show');
                });
                document.querySelectorAll('.fa-chevron-down').forEach(arrow => {
                    arrow.style.transform = 'rotate(0deg)';
                });
            }
        });
        window.dropdownsDelegated = true; // عشان نمنع تكرار الـ Event Listener
    }
}
