function renderCalendar() {
    window.CITLRoomAvailability?.week(currentWeekStart);
    window.CITLAcademicBooking.load(supabase,currentRoomId,currentWeekStart,renderCalendar);
    window.CITLMeetingUI?.weekPicker(currentWeekStart);
    const container = document.getElementById('calendar-container');
    if (!container) return; // حماية للتأكد من وجود الحاوية
    container.innerHTML = '';

    // 1. تصميم رأس الجدول (الأيام)
    const dayNames = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
    const dates = window.CITLAcademicBooking.weekDays(currentWeekStart);
    
    for (let i = 0; i <= dates.length; i++) {
        const cell = document.createElement('div');
        
        if (i === 0) {
             // === خانة الوقت (الرأس) ===
             cell.className = 'time-slot sticky right-0 z-20 bg-gray-100 text-[#2A3475] font-extrabold text-xs flex items-center justify-center border-b-2 border-[#F3A628] shadow-[2px_0_5px_rgba(0,0,0,0.05)]';
             cell.textContent = 'الوقت';
        } else {
             // === خانات الأيام (الرأس) ===
             const dayIndex = i - 1;
             const dateObj = dates[dayIndex];
             cell.dataset.calendarDate = window.CITLAcademicBooking.dateKey(dateObj);
             cell.dataset.calendarHeader = "true";
             const dateStr = dateObj.toLocaleDateString('ar-EG', { day: 'numeric', month: 'numeric' });

cell.className = 'time-slot metallic-blue-fill random-slanted-lines text-white font-bold flex flex-col items-center justify-center tracking-wide border-l border-blue-800 py-1';             cell.innerHTML = `
                <span class="text-xs md:text-sm font-extrabold mb-0.5">${dayNames[dateObj.getDay()]}</span>
                <span class="text-[9px] md:text-xs text-[#F3A628] font-bold bg-white/10 px-2 py-0.5 rounded-full border border-[#F3A628]/20">${dateStr}</span>
             `;
        }
        container.appendChild(cell);
    }

    // Exact minute boundaries keep 08:30–10:20 lectures out of the 08:00 slot.
    const academic=window.CITLAcademicBooking;
    const calendarMeetings=meetings.filter(m=>m.booking_type!=='lecture'&&(!currentRoomId||String(m.room_id)===String(currentRoomId)));
    const intervals=academic.timeline(currentRoomId,currentWeekStart,timeSlots,calendarMeetings,!!currentRoom?.academic_room_name);
    const covered=new Map();
    const meetingAt=(date,slot)=>calendarMeetings.find(m=>m.date===academic.dateKey(date)&&timeToMinutes(m.startTime)<slot.end&&timeToMinutes(m.endTime)>slot.start&&['confirmed','modification_requested','cancellation_requested'].includes(m.status));
    const identity=(date,slot)=>{const m=meetingAt(date,slot);return m?'meeting:'+m.id:academic.rowsFor(currentRoomId,currentWeekStart,date,slot.start,slot.end).map(r=>'lecture:'+r.schedule_id).sort().join('|');};
    container.style.gridTemplateRows='70px '+intervals.map(slot=>Math.max(22,Math.round((slot.end-slot.start)*.85))+'px').join(' ');
    intervals.forEach((slot,rowIndex) => {
        const time=slot.time;
        // عمود الوقت الجانبي
        const timeLabel = document.createElement('div');
        timeLabel.className = 'time-slot sticky right-0 z-20 bg-gray-50 flex items-center justify-center font-bold text-[#2A3475] border-b border-gray-200 text-xs md:text-sm shadow-[2px_0_5px_rgba(0,0,0,0.05)]';
        timeLabel.textContent = toArabicNum(time+' – '+slot.endTime);
        timeLabel.style.cssText='grid-column:1;grid-row:'+(rowIndex+2)+';min-height:0;font-size:10px;direction:ltr';
        container.appendChild(timeLabel);

        for (const [dayIndex,currentDate] of dates.entries()) {
            if((covered.get(dayIndex)||0)>rowIndex)continue;
            const signature=identity(currentDate,slot);let span=1;
            if(signature)while(rowIndex+span<intervals.length&&identity(currentDate,intervals[rowIndex+span])===signature)span++;
            covered.set(dayIndex,rowIndex+span);
            const finalSlot=intervals[rowIndex+span-1];
            const cell = document.createElement('div');
            cell.className = 'time-slot relative border-b border-l border-gray-100 cursor-pointer transition-all duration-200 hover:bg-blue-50 hover:shadow-inner group min-h-[70px]';
            
            cell.dataset.calendarDate = window.CITLAcademicBooking.dateKey(currentDate);
            cell.dataset.calendarTime = time;
            cell.dataset.calendarEnd=finalSlot.endTime;
            cell.style.gridColumn=String(dayIndex+2);cell.style.gridRow=(rowIndex+2)+' / span '+span;cell.style.minHeight='0';
            
            // التعديل 1: البحث عن الحجوزات المؤكدة (confirmed) فقط لتظهر في الجدول
            const meeting = meetingAt(currentDate,slot);

            if (meeting) {
                const meetingBlock = document.createElement('div');
                meetingBlock.dataset.bookingId=String(meeting.id);
                const nowParts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(x=>[x.type,x.value]));
                const today=nowParts.year+'-'+nowParts.month+'-'+nowParts.day,expired=meeting.date<today||(meeting.date===today&&timeToMinutes(meeting.endTime)<=Number(nowParts.hour)*60+Number(nowParts.minute));
                meetingBlock.className = `meeting-block ${expired?'bg-gray-400 text-white':(departments[meeting.department]||departments['other']||{color:'bg-[#2A3475]'}).color} shadow-md rounded border-r-4 border-black/20 hover:scale-[1.02] transition-transform z-10 h-[calc(100%-8px)] m-1`;
                
                if(timeToMinutes(meeting.endTime)-timeToMinutes(meeting.startTime)<=20)meetingBlock.classList.add('citl-short-booking');
                meetingBlock.title=meeting.title+' · '+meeting.startTime+' – '+meeting.endTime;
                meetingBlock.setAttribute('role','button');meetingBlock.tabIndex=0;
                meetingBlock.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();meetingBlock.click();}});
                // التعديل 2: إضافة الجهة الحاجزة وتنسيق المحتوى ليكون متجاوباً مع الموبايل والكمبيوتر
                meetingBlock.innerHTML = `
                    <div class="p-1 md:p-1.5 h-full flex flex-col justify-between overflow-hidden text-white">
                        <div class="flex flex-col gap-0.5">
                            <p class="text-[9px] md:text-[11px] font-black leading-tight truncate text-right">
                                ${window.CITLSecure.htmlEscape(meeting.title)}
                            </p>
                            <p class="text-[7px] md:text-[9px] font-bold opacity-90 truncate text-right flex items-center justify-start gap-1">
                                <i class="fas fa-building text-[6px] md:text-[8px] opacity-70"></i>
                                <span>${window.CITLSecure.htmlEscape(departments[meeting.department]?.name||meeting.department||'غير محدد')}</span>
                            </p>
                        </div>
                        
                        <div class="flex items-center justify-between mt-0.5 border-t border-white/20 pt-0.5">
                            <span class="text-[8px] md:text-[10px] font-bold opacity-90 whitespace-nowrap">
                                ${window.CITLSecure.htmlEscape(toArabicNum(meeting.startTime+' – '+meeting.endTime))}
                            </span>
                            <i class="fas fa-bookmark text-[7px] md:text-[9px] opacity-60"></i>
                        </div>
                    </div>
                `;
                
                meetingBlock.addEventListener('click', (e) => {
                    e.stopPropagation();
                    if(window.CITLMeetingUI)window.CITLMeetingUI.open(meeting.id,true);else showMeetingDetails(meeting);
                });
                cell.appendChild(meetingBlock);
            } else if(slot.isBreak&&!signature) {
                cell.classList.add('citl-calendar-break');cell.textContent='استراحة';cell.dataset.calendarBreak='true';
                cell.addEventListener('click',()=>{openAddMeetingModal(currentDate,time);academic.setTiming(time,(finalSlot.end-slot.start)/60);});
            } else {
                const addIcon = document.createElement('div');
                addIcon.className = 'absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none';
                addIcon.innerHTML = '<i class="fas fa-plus text-[#F3A628] text-xl opacity-50"></i>';
                cell.appendChild(addIcon);

                window.CITLAcademicBooking.paint(cell,supabase,currentRoomId,currentWeekStart,currentDate,time,() => {
                    openAddMeetingModal(currentDate,time);
                    // Use the complete displayed interval, including paired academic periods.
                    academic.setTiming(time,(finalSlot.end-slot.start)/60);
                },finalSlot.end);
            }
            container.appendChild(cell);
        }
    });

    // 3. فحص الحجوزات المخفية
    if (typeof checkHiddenMeetings === 'function') {
        setTimeout(checkHiddenMeetings, 100);
    }
}
function updateWeekDisplay() {
    const weekEnd = new Date(currentWeekStart);
    weekEnd.setDate(weekEnd.getDate() + 5);
    
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    const startStr = currentWeekStart.toLocaleDateString('ar-EG', options);
    const endStr = weekEnd.toLocaleDateString('ar-EG', options);
    
    const weekDisplaySpan = document.getElementById('current-week');
    
    // 🔥 إزالة الـ Skeleton وإظهار التاريخ
    if(weekDisplaySpan) {
        weekDisplaySpan.textContent = `${startStr} - ${endStr}`;
        // إزالة كلاسات الـ Skeleton بمجرد تحميل البيانات
        weekDisplaySpan.classList.remove('animate-pulse', 'bg-gray-200', 'h-6');
        weekDisplaySpan.style.minWidth = 'auto';
    }

    // 🔥 تعبئة خيارات القائمة المنسدلة
    const dropdownOptions = document.getElementById('week-dropdown-options');
    if (!dropdownOptions) return;
    
    dropdownOptions.innerHTML = '';
    
    // ننشئ خيارات للأسابيع (الأسبوع الحالي، 3 أسابيع سابقة، 3 أسابيع قادمة)
    for (let i = -3; i <= 3; i++) {
        const weekDate = new Date(currentWeekStart);
        weekDate.setDate(currentWeekStart.getDate() + (i * 7));
        
        const weekEndDisplay = new Date(weekDate);
        weekEndDisplay.setDate(weekEndDisplay.getDate() + 5);
        
        const startText = weekDate.toLocaleDateString('ar-EG', { month: 'short', day: 'numeric' });
        const endText = weekEndDisplay.toLocaleDateString('ar-EG', { month: 'short', day: 'numeric' });
        
        const isCurrent = i === 0;
        const text = isCurrent ? `الأسبوع الحالي: ${startText} - ${endText}` : `${startText} - ${endText}`;
        const value = weekDate.toISOString(); // نحفظ التاريخ كـ ISO string

        dropdownOptions.innerHTML += `
            <li class="custom-option px-4 py-2.5 hover:bg-[#2A3475] hover:text-white cursor-pointer text-sm font-bold border-b border-gray-50 transition-all ${isCurrent ? 'bg-[#2A3475] text-white selected' : 'text-gray-700'}" 
                data-value="${value}" 
                onclick="jumpToWeek('${value}')">
                ${text}
            </li>
        `;
    }
}
function timeToMinutes(time) {
            // لو الوقت فاضي أو مش نص، نرجع 0 عشان الكود ميرميش Error
            if (!time || typeof time !== 'string') return 0;
            
            try {
                const [hours, minutes] = time.split(':').map(Number);
                return hours * 60 + minutes;
            } catch (e) {
                return 0;
            }
        }
function toArabicNum(str) {
    // 1. الحماية: إذا كانت القيمة null أو undefined فعلاً، ارجع نص فارغ
    if (str === null || str === undefined) return '';
    
    // 2. التحويل: الآن حتى لو القيمة 0 (رقم)، سيتم تحويلها لنص ثم لـ "٠"
    return str.toString().replace(/\d/g, d => "٠١٢٣٤٥٦٧٨٩"[d]);
}
function renderUpcoming(){const host=document.getElementById('ai-suggestions');if(!host||root.CITLRoomAvailability?.isFree())return;const now=cairo(),rows=(upcomingRows||[]).filter(m=>m.booking_type!=='lecture').filter(m=>(m.date>now.date||(m.date===now.date&&mins(m.end_time)>now.minutes)));
  rows.sort((a,b)=>(a.date+' '+a.start_time).localeCompare(b.date+' '+b.start_time));
  const approved=rows.filter(m=>m.status!=='pending').length;
  const text=rows.length?'<div class="citl-upcoming-summary"><span><strong>مواعيد جميع القاعات</strong><small>مرتبة من الأقرب · مواعيد قادمة حتى خارج الجدول المعروض</small></span><span class="citl-upcoming-count"><b>'+approved+'</b> معتمد'+(rows.length-approved?' · '+(rows.length-approved)+' بانتظار الاعتماد':'')+'</span></div><div class="citl-upcoming-meetings">'+rows.slice(0,visibleUpcoming).map((m,i)=>'<article data-status="'+E(m.status)+'"><button type="button" data-open-booking="'+E(m.id)+'"><span class="citl-upcoming-card-top"><small class="citl-upcoming-state">'+E(labels[m.status])+'</small>'+(i===0?'<small class="citl-upcoming-nearest">أقرب موعد</small>':'')+'</span><strong>'+E(m.title)+'</strong><span>'+E(m.rooms?.name||'قاعة')+' · '+E(department(m.department))+'</span><span>'+E(new Date(m.date+'T12:00:00Z').toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'}))+'</span><span class="citl-upcoming-time"><bdi>'+E(clock(m.start_time)+' – '+clock(m.end_time))+'</bdi><small>'+E(kind(m))+' · '+E(duration(m.start_time,m.end_time))+'</small></span></button><div class="citl-upcoming-actions"><button type="button" data-detail-booking="'+E(m.id)+'">تفاصيل الحجز</button><button type="button" data-locate-booking="'+E(m.id)+'">عرض في الجدول ←</button></div></article>').join('')+'</div>'+(rows.length>visibleUpcoming?'<button type="button" class="citl-upcoming-more" data-more-bookings>عرض حجوزات أخرى ('+(rows.length-visibleUpcoming)+')</button>':'')+(rows.length===100?'<small class="citl-upcoming-limit">تُعرض أقرب 100 نتيجة. جميع الحجوزات في إدارة الحجوزات.</small>':''):'<div class="citl-admin-empty">لا توجد حجوزات قاعات قادمة متاحة للعرض.</div>';
  if(host.innerHTML!==text){host.innerHTML=text;host.dataset.upcoming=text;host.querySelectorAll('[data-open-booking],[data-detail-booking]').forEach(b=>b.onclick=()=>previewOpenMeeting(b.dataset.openBooking||b.dataset.detailBooking,true));host.querySelectorAll('[data-locate-booking]').forEach(b=>b.onclick=()=>locate(b.dataset.locateBooking));host.querySelector('[data-more-bookings]')?.addEventListener('click',()=>{visibleUpcoming+=6;renderUpcoming();});}

 }
function duration(start,end){const n=Math.round(mins(end)-mins(start));if(!Number.isFinite(n)||n<0)return 'غير محددة';const h=Math.floor(n/60),m=n%60;return [h?(h===1?'ساعة':h===2?'ساعتان':h+' ساعات'):'',m?m+' دقيقة':''].filter(Boolean).join(' و')||'0 دقيقة';}
function kind(m){return m.booking_type==='lecture'?'محاضرة / سكشن':reasons[m.booking_reason]|| (m.booking_type==='other'?'استخدام إداري / آخر':'اجتماع');}
function details(m){return [['نوع الحجز',kind(m)],['الجهة الحاجزة',department(m.department)],['القاعة',m.rooms?.name||m.room_name|| (typeof rooms!=='undefined'?rooms.find(r=>String(r.id)===String(m.room_id))?.name:null)||'—'],['مقدم الطلب',m.createdBy||'—'],['بريد مقدم الطلب',m.creatorEmail||'—'],['الحالة',labels[m.status]||m.status],['سبب الحجز',m.booking_reason_detail||'لم تُضف تفاصيل للسبب']];}
function normalize(m){return {...m,startTime:clock(m.startTime||m.start_time),endTime:clock(m.endTime||m.end_time),createdAt:m.createdAt||m.created_at,createdBy:m.profiles?.full_name||m.createdBy||'',creatorEmail:m.profiles?.email||m.creatorEmail||null};}
